mapper.select:
select ido.*
from idevelop_device_operation ido left join idevelop_device_operation_detail idod on ido.id = idod.operation_id

    ido.is_deleted = 0
    
        AND idod.device_code LIKE CONCAT('%', #{deviceOperationDTO.deviceCode}, '%')
    
    
        AND ido.outbound_no LIKE CONCAT('%', #{deviceOperationDTO.outboundNo}, '%')
    
    
        AND ido.operation_no LIKE CONCAT('%', #{deviceOperationDTO.operationNo}, '%')
    
    
        AND ido.apply_no LIKE CONCAT('%', #{deviceOperationDTO.applyNo}, '%')
    
    
        AND ido.device_category = #{deviceOperationDTO.deviceCategory}
    
    
        AND ido.device_type = #{deviceOperationDTO.deviceType}
    
    
        AND ido.old_to_new = #{deviceOperationDTO.oldToNew}
    
    
        AND ido.region_code LIKE CONCAT(#{deviceOperationDTO.regionCode}, '%')
    
    
        AND ido.receive_unit = #{deviceOperationDTO.receiveUnit}
    
    
        AND ido.operation_type = #{deviceOperationDTO.operationType}
    
    
        AND ido.receive_duty_dept = #{deviceOperationDTO.receiveDutyDept}
    
    GROUP BY ido.id ORDER BY ido.create_time DESC
